/// Describes a task in a checklist
final class ChecklistTask extends TdObject {
  const ChecklistTask({
    required this.id,
    required this.text,
    this.completedBy,
    required this.completionDate,
  });

  factory ChecklistTask.fromJson(Map<String, Object?> json) => ChecklistTask(
    id: tdInt(json['id']),
    text: tdObject<FormattedText>(json['text'], tdFromJson),
    completedBy: tdObjectOrNull<MessageSender>(
      json['completed_by'],
      tdFromJson,
    ),
    completionDate: tdInt(json['completion_date']),
  );

  static const String constructor = 'checklistTask';

  /// Unique identifier of the task
  final int id;

  /// Text of the task; may contain only Bold, Italic, Underline, Strikethrough, Spoiler, CustomEmoji, DateTime and automatically found entities
  final FormattedText text;

  /// Identifier of the user or chat that completed the task; may be null if the task isn't completed yet
  final MessageSender? completedBy;

  /// Point in time (Unix timestamp) when the task was completed; 0 if the task isn't completed
  final int completionDate;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'id': id,
    'text': text.toJson(),
    if (completedBy != null) 'completed_by': completedBy!.toJson(),
    'completion_date': completionDate,
  };
}

