/// Describes an animation file. The animation must be encoded in GIF or MPEG4 format
final class Animation extends TdObject {
  const Animation({
    required this.duration,
    required this.width,
    required this.height,
    required this.fileName,
    required this.mimeType,
    required this.hasStickers,
    this.minithumbnail,
    this.thumbnail,
    required this.animation,
  });

  factory Animation.fromJson(Map<String, Object?> json) => Animation(
    duration: tdInt(json['duration']),
    width: tdInt(json['width']),
    height: tdInt(json['height']),
    fileName: tdString(json['file_name']),
    mimeType: tdString(json['mime_type']),
    hasStickers: tdBool(json['has_stickers']),
    minithumbnail: tdObjectOrNull<Minithumbnail>(
      json['minithumbnail'],
      tdFromJson,
    ),
    thumbnail: tdObjectOrNull<Thumbnail>(json['thumbnail'], tdFromJson),
    animation: tdObject<File>(json['animation'], tdFromJson),
  );

  static const String constructor = 'animation';

  /// Duration of the animation, in seconds; as defined by the sender
  final int duration;

  /// Width of the animation
  final int width;

  /// Height of the animation
  final int height;

  /// Original name of the file; as defined by the sender
  final String fileName;

  /// MIME type of the file, usually "image/gif" or "video/mp4"
  final String mimeType;

  /// True, if stickers were added to the animation. The list of corresponding sticker sets can be received using getAttachedStickerSets
  final bool hasStickers;

  /// Animation minithumbnail; may be null
  final Minithumbnail? minithumbnail;

  /// Animation thumbnail in JPEG or MPEG4 format; may be null
  final Thumbnail? thumbnail;

  /// File containing the animation
  final File animation;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'duration': duration,
    'width': width,
    'height': height,
    'file_name': fileName,
    'mime_type': mimeType,
    'has_stickers': hasStickers,
    if (minithumbnail != null) 'minithumbnail': minithumbnail!.toJson(),
    if (thumbnail != null) 'thumbnail': thumbnail!.toJson(),
    'animation': animation.toJson(),
  };
}

/// Describes an audio file. Audio is usually in MP3 or M4A format
final class Audio extends TdObject {
  const Audio({
    required this.duration,
    required this.title,
    required this.performer,
    required this.fileName,
    required this.mimeType,
    this.albumCoverMinithumbnail,
    this.albumCoverThumbnail,
    required this.externalAlbumCovers,
    required this.audio,
  });

  factory Audio.fromJson(Map<String, Object?> json) => Audio(
    duration: tdInt(json['duration']),
    title: tdString(json['title']),
    performer: tdString(json['performer']),
    fileName: tdString(json['file_name']),
    mimeType: tdString(json['mime_type']),
    albumCoverMinithumbnail: tdObjectOrNull<Minithumbnail>(
      json['album_cover_minithumbnail'],
      tdFromJson,
    ),
    albumCoverThumbnail: tdObjectOrNull<Thumbnail>(
      json['album_cover_thumbnail'],
      tdFromJson,
    ),
    externalAlbumCovers: tdList(
      json['external_album_covers'],
      (e) => tdObject<Thumbnail>(e, tdFromJson),
    ),
    audio: tdObject<File>(json['audio'], tdFromJson),
  );

  static const String constructor = 'audio';

  /// Duration of the audio, in seconds; as defined by the sender
  final int duration;

  /// Title of the audio; as defined by the sender
  final String title;

  /// Performer of the audio; as defined by the sender
  final String performer;

  /// Original name of the file; as defined by the sender
  final String fileName;

  /// The MIME type of the file; as defined by the sender
  final String mimeType;

  /// The minithumbnail of the album cover; may be null
  final Minithumbnail? albumCoverMinithumbnail;

  /// The thumbnail of the album cover in JPEG format; as defined by the sender. The full size thumbnail is expected to be extracted from the downloaded audio file; may be null
  final Thumbnail? albumCoverThumbnail;

  /// Album cover variants to use if the downloaded audio file contains no album cover. Provided thumbnail dimensions are approximate
  final List<Thumbnail> externalAlbumCovers;

  /// File containing the audio
  final File audio;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'duration': duration,
    'title': title,
    'performer': performer,
    'file_name': fileName,
    'mime_type': mimeType,
