      'album_cover_minithumbnail': albumCoverMinithumbnail!.toJson(),
    if (albumCoverThumbnail != null)
      'album_cover_thumbnail': albumCoverThumbnail!.toJson(),
    'external_album_covers': [for (final e in externalAlbumCovers) e.toJson()],
    'audio': audio.toJson(),
  };
}

