    speechRecognitionResult: tdObjectOrNull<SpeechRecognitionResult>(
      json['speech_recognition_result'],
      tdFromJson,
    ),
    video: tdObject<File>(json['video'], tdFromJson),
  );

  static const String constructor = 'videoNote';

  /// Duration of the video, in seconds; as defined by the sender
  final int duration;

  /// A waveform representation of the video note's audio in 5-bit format; may be empty if unknown
  final Uint8List waveform;

  /// Video width and height; as defined by the sender
  final int length;

  /// Video minithumbnail; may be null
  final Minithumbnail? minithumbnail;

  /// Video thumbnail in JPEG format; as defined by the sender; may be null
  final Thumbnail? thumbnail;

  /// Result of speech recognition in the video note; may be null
  final SpeechRecognitionResult? speechRecognitionResult;

  /// File containing the video
