  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'duration': duration,
    'waveform': base64.encode(waveform),
    'length': length,
    if (minithumbnail != null) 'minithumbnail': minithumbnail!.toJson(),
    if (thumbnail != null) 'thumbnail': thumbnail!.toJson(),
    if (speechRecognitionResult != null)
      'speech_recognition_result': speechRecognitionResult!.toJson(),
    'video': video.toJson(),
  };
}

