  factory UpgradedGiftModel.fromJson(Map<String, Object?> json) =>
      UpgradedGiftModel(
        name: tdString(json['name']),
        sticker: tdObject<Sticker>(json['sticker'], tdFromJson),
        rarity: tdObject<UpgradedGiftAttributeRarity>(
          json['rarity'],
          tdFromJson,
        ),
        isCrafted: tdBool(json['is_crafted']),
      );

  static const String constructor = 'upgradedGiftModel';

  /// Name of the model
