/// Describes the original details about the gift
final class UpgradedGiftOriginalDetails extends TdObject {
  const UpgradedGiftOriginalDetails({
    this.senderId,
    required this.receiverId,
    required this.text,
    required this.date,
  });

  factory UpgradedGiftOriginalDetails.fromJson(Map<String, Object?> json) =>
      UpgradedGiftOriginalDetails(
        senderId: tdObjectOrNull<MessageSender>(json['sender_id'], tdFromJson),
        receiverId: tdObject<MessageSender>(json['receiver_id'], tdFromJson),
        text: tdObject<FormattedText>(json['text'], tdFromJson),
        date: tdInt(json['date']),
      );

  static const String constructor = 'upgradedGiftOriginalDetails';

  /// Identifier of the user or the chat that sent the gift; may be null if the gift was private
  final MessageSender? senderId;

  /// Identifier of the user or the chat that received the gift
  final MessageSender receiverId;

  /// Message added to the gift
  final FormattedText text;

  /// Point in time (Unix timestamp) when the gift was sent
  final int date;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    if (senderId != null) 'sender_id': senderId!.toJson(),
    'receiver_id': receiverId.toJson(),
    'text': text.toJson(),
    'date': date,
  };
}

/// Contains information about color scheme for user's name, background of empty chat photo, replies to messages and link previews
