  const UpgradedGiftColors({
    required this.id,
    required this.modelCustomEmojiId,
    required this.symbolCustomEmojiId,
    required this.lightThemeAccentColor,
    required this.lightThemeColors,
    required this.darkThemeAccentColor,
    required this.darkThemeColors,
  });

  factory UpgradedGiftColors.fromJson(Map<String, Object?> json) =>
      UpgradedGiftColors(
        id: tdInt64(json['id']),
        modelCustomEmojiId: tdInt64(json['model_custom_emoji_id']),
        symbolCustomEmojiId: tdInt64(json['symbol_custom_emoji_id']),
        lightThemeAccentColor: tdInt(json['light_theme_accent_color']),
        lightThemeColors: tdList(json['light_theme_colors'], (e) => tdInt(e)),
        darkThemeAccentColor: tdInt(json['dark_theme_accent_color']),
        darkThemeColors: tdList(json['dark_theme_colors'], (e) => tdInt(e)),
      );

  static const String constructor = 'upgradedGiftColors';

  /// Unique identifier of the upgraded gift colors
  final int id;

  /// Custom emoji identifier of the model of the upgraded gift
  final int modelCustomEmojiId;

  /// Custom emoji identifier of the symbol of the upgraded gift
