    name: tdString(json['name']),
    photo: tdObjectOrNull<ChatPhotoInfo>(json['photo'], tdFromJson),
    date: tdInt(json['date']),
    status: tdObject<CommunityMemberStatus>(json['status'], tdFromJson),
    permissions: tdObject<CommunityPermissions>(
      json['permissions'],
      tdFromJson,
    ),
  );

  static const String constructor = 'community';

