/// Represents a user
final class User extends TdObject {
  const User({
    required this.id,
    required this.firstName,
    required this.lastName,
    this.usernames,
    required this.phoneNumber,
    required this.status,
    this.profilePhoto,
    required this.accentColorId,
    required this.backgroundCustomEmojiId,
    this.upgradedGiftColors,
    required this.profileAccentColorId,
    required this.profileBackgroundCustomEmojiId,
    this.emojiStatus,
    required this.isContact,
    required this.isMutualContact,
    required this.isCloseFriend,
    this.verificationStatus,
    required this.isPremium,
    required this.isSupport,
    this.restrictionInfo,
    this.activeStoryState,
    required this.restrictsNewChats,
    required this.paidMessageStarCount,
    required this.haveAccess,
    required this.type,
    required this.languageCode,
    required this.addedToAttachmentMenu,
  });

  factory User.fromJson(Map<String, Object?> json) => User(
    id: tdInt(json['id']),
    firstName: tdString(json['first_name']),
    lastName: tdString(json['last_name']),
    usernames: tdObjectOrNull<Usernames>(json['usernames'], tdFromJson),
    phoneNumber: tdString(json['phone_number']),
    status: tdObject<UserStatus>(json['status'], tdFromJson),
    profilePhoto: tdObjectOrNull<ProfilePhoto>(
      json['profile_photo'],
      tdFromJson,
    ),
    accentColorId: tdInt(json['accent_color_id']),
    backgroundCustomEmojiId: tdInt64(json['background_custom_emoji_id']),
    upgradedGiftColors: tdObjectOrNull<UpgradedGiftColors>(
      json['upgraded_gift_colors'],
      tdFromJson,
    ),
    profileAccentColorId: tdInt(json['profile_accent_color_id']),
    profileBackgroundCustomEmojiId: tdInt64(
      json['profile_background_custom_emoji_id'],
    ),
    emojiStatus: tdObjectOrNull<EmojiStatus>(json['emoji_status'], tdFromJson),
    isContact: tdBool(json['is_contact']),
    isMutualContact: tdBool(json['is_mutual_contact']),
    isCloseFriend: tdBool(json['is_close_friend']),
    verificationStatus: tdObjectOrNull<VerificationStatus>(
      json['verification_status'],
      tdFromJson,
    ),
    isPremium: tdBool(json['is_premium']),
    isSupport: tdBool(json['is_support']),
    restrictionInfo: tdObjectOrNull<RestrictionInfo>(
      json['restriction_info'],
      tdFromJson,
    ),
    activeStoryState: tdObjectOrNull<ActiveStoryState>(
      json['active_story_state'],
      tdFromJson,
    ),
    restrictsNewChats: tdBool(json['restricts_new_chats']),
    paidMessageStarCount: tdInt(json['paid_message_star_count']),
    haveAccess: tdBool(json['have_access']),
    type: tdObject<UserType>(json['type'], tdFromJson),
    languageCode: tdString(json['language_code']),
    addedToAttachmentMenu: tdBool(json['added_to_attachment_menu']),
  );

  static const String constructor = 'user';

  /// User identifier
  final int id;

  /// First name of the user
  final String firstName;

  /// Last name of the user
  final String lastName;

  /// Usernames of the user; may be null
  final Usernames? usernames;

  /// Phone number of the user
  final String phoneNumber;

  /// Current online status of the user
  final UserStatus status;

  /// Profile photo of the user; may be null
  final ProfilePhoto? profilePhoto;

  /// Identifier of the accent color for name, and backgrounds of profile photo, reply header, and link preview
  final int accentColorId;

  /// Identifier of a custom emoji to be shown on the reply header and link preview background; 0 if none
  final int backgroundCustomEmojiId;

  /// Color scheme based on an upgraded gift to be used for the user instead of accent_color_id and background_custom_emoji_id; may be null if none
  final UpgradedGiftColors? upgradedGiftColors;

  /// Identifier of the accent color for the user's profile; -1 if none
  final int profileAccentColorId;

  /// Identifier of a custom emoji to be shown on the background of the user's profile; 0 if none
  final int profileBackgroundCustomEmojiId;

  /// Emoji status to be shown instead of the default Telegram Premium badge; may be null
  final EmojiStatus? emojiStatus;

  /// The user is a contact of the current user
  final bool isContact;

  /// The user is a contact of the current user and the current user is a contact of the user
  final bool isMutualContact;

  /// The user is a close friend of the current user; implies that the user is a contact
  final bool isCloseFriend;

  /// Information about verification status of the user; may be null if none
  final VerificationStatus? verificationStatus;

  /// True, if the user is a Telegram Premium user
  final bool isPremium;

  /// True, if the user is Telegram support account
  final bool isSupport;

  /// Information about restrictions that must be applied to the corresponding private chat; may be null if none
  final RestrictionInfo? restrictionInfo;

  /// State of active stories of the user; may be null if the user has no active stories
  final ActiveStoryState? activeStoryState;

  /// True, if the user may restrict new chats with non-contacts. Use canSendMessageToUser to check whether the current user can message the user or try to create a chat with them
  final bool restrictsNewChats;

  /// Number of Telegram Stars that must be paid by general user for each sent message to the user. If positive and userFullInfo is unknown, use canSendMessageToUser to check whether the current user must pay
  final int paidMessageStarCount;

  /// If false, the user is inaccessible, and the only information known about the user is inside this class. Identifier of the user can't be passed to any method
  final bool haveAccess;

  /// Type of the user
  final UserType type;

  /// IETF language tag of the user's language; only available to bots
  final String languageCode;

  /// True, if the user added the current bot to attachment menu; only available to bots
  final bool addedToAttachmentMenu;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'id': id,
    'first_name': firstName,
    'last_name': lastName,
    if (usernames != null) 'usernames': usernames!.toJson(),
    'phone_number': phoneNumber,
    'status': status.toJson(),
    if (profilePhoto != null) 'profile_photo': profilePhoto!.toJson(),
    'accent_color_id': accentColorId,
    'background_custom_emoji_id': backgroundCustomEmojiId.toString(),
    if (upgradedGiftColors != null)
      'upgraded_gift_colors': upgradedGiftColors!.toJson(),
    'profile_accent_color_id': profileAccentColorId,
    'profile_background_custom_emoji_id': profileBackgroundCustomEmojiId
        .toString(),
    if (emojiStatus != null) 'emoji_status': emojiStatus!.toJson(),
    'is_contact': isContact,
    'is_mutual_contact': isMutualContact,
    'is_close_friend': isCloseFriend,
    if (verificationStatus != null)
      'verification_status': verificationStatus!.toJson(),
    'is_premium': isPremium,
    'is_support': isSupport,
    if (restrictionInfo != null) 'restriction_info': restrictionInfo!.toJson(),
    if (activeStoryState != null)
      'active_story_state': activeStoryState!.toJson(),
    'restricts_new_chats': restrictsNewChats,
    'paid_message_star_count': paidMessageStarCount,
    'have_access': haveAccess,
    'type': type.toJson(),
    'language_code': languageCode,
    'added_to_attachment_menu': addedToAttachmentMenu,
  };
}

/// Contains information about a bot
final class BotInfo extends TdObject {
  const BotInfo({
    required this.shortDescription,
    required this.description,
    this.photo,
    this.animation,
    required this.managerBotUserId,
    this.menuButton,
