    communityId: tdInt(json['community_id']),
    blockList: tdObjectOrNull<BlockList>(json['block_list'], tdFromJson),
    canBeCalled: tdBool(json['can_be_called']),
    supportsVideoCalls: tdBool(json['supports_video_calls']),
    hasPrivateCalls: tdBool(json['has_private_calls']),
    hasPrivateForwards: tdBool(json['has_private_forwards']),
    hasRestrictedVoiceAndVideoNoteMessages: tdBool(
      json['has_restricted_voice_and_video_note_messages'],
    ),
    hasPostedToProfileStories: tdBool(json['has_posted_to_profile_stories']),
    hasSponsoredMessagesEnabled: tdBool(json['has_sponsored_messages_enabled']),
    needPhoneNumberPrivacyException: tdBool(
      json['need_phone_number_privacy_exception'],
    ),
    setChatBackground: tdBool(json['set_chat_background']),
    usesUnofficialApp: tdBool(json['uses_unofficial_app']),
    bio: tdObjectOrNull<FormattedText>(json['bio'], tdFromJson),
    birthdate: tdObjectOrNull<Birthdate>(json['birthdate'], tdFromJson),
    personalChatId: tdInt(json['personal_chat_id']),
