/// Contains information about a chat invite link
final class ChatInviteLinkInfo extends TdObject {
  const ChatInviteLinkInfo({
    required this.chatId,
    required this.accessibleFor,
    required this.type,
    required this.title,
    this.photo,
    required this.accentColorId,
    required this.description,
    required this.memberCount,
    required this.memberUserIds,
    this.subscriptionInfo,
    required this.createsJoinRequest,
    required this.isPublic,
    this.verificationStatus,
  });

  factory ChatInviteLinkInfo.fromJson(Map<String, Object?> json) =>
      ChatInviteLinkInfo(
        chatId: tdInt(json['chat_id']),
        accessibleFor: tdInt(json['accessible_for']),
        type: tdObject<InviteLinkChatType>(json['type'], tdFromJson),
        title: tdString(json['title']),
        photo: tdObjectOrNull<ChatPhotoInfo>(json['photo'], tdFromJson),
        accentColorId: tdInt(json['accent_color_id']),
        description: tdString(json['description']),
        memberCount: tdInt(json['member_count']),
        memberUserIds: tdList(json['member_user_ids'], (e) => tdInt(e)),
        subscriptionInfo: tdObjectOrNull<ChatInviteLinkSubscriptionInfo>(
          json['subscription_info'],
          tdFromJson,
        ),
        createsJoinRequest: tdBool(json['creates_join_request']),
        isPublic: tdBool(json['is_public']),
        verificationStatus: tdObjectOrNull<VerificationStatus>(
          json['verification_status'],
          tdFromJson,
        ),
      );

  static const String constructor = 'chatInviteLinkInfo';

  /// Chat identifier of the invite link; 0 if the user has no access to the chat before joining
  final int chatId;

  /// If non-zero, the amount of time for which read access to the chat will remain available, in seconds
  final int accessibleFor;

  /// Type of the chat
  final InviteLinkChatType type;

  /// Title of the chat
  final String title;

  /// Chat photo; may be null
  final ChatPhotoInfo? photo;

  /// Identifier of the accent color for chat title and background of chat photo
  final int accentColorId;

  /// Chat description
  final String description;

  /// Number of members in the chat
  final int memberCount;

  /// User identifiers of some chat members that may be known to the current user
  final List<int> memberUserIds;

  /// Information about subscription plan that must be paid by the user to use the link; may be null if the link doesn't require subscription
  final ChatInviteLinkSubscriptionInfo? subscriptionInfo;

  /// True, if the link only creates join request
  final bool createsJoinRequest;

  /// True, if the chat is a public supergroup or channel, i.e. it has a username or it is a location-based supergroup
  final bool isPublic;

  /// Information about verification status of the chat; may be null if none
  final VerificationStatus? verificationStatus;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'chat_id': chatId,
    'accessible_for': accessibleFor,
    'type': type.toJson(),
    'title': title,
    if (photo != null) 'photo': photo!.toJson(),
    'accent_color_id': accentColorId,
    'description': description,
    'member_count': memberCount,
    'member_user_ids': memberUserIds,
    if (subscriptionInfo != null)
      'subscription_info': subscriptionInfo!.toJson(),
    'creates_join_request': createsJoinRequest,
    'is_public': isPublic,
    if (verificationStatus != null)
      'verification_status': verificationStatus!.toJson(),
  };
}

