/// Represents a secret chat
final class SecretChat extends TdObject {
  const SecretChat({
    required this.id,
    required this.userId,
    required this.state,
    required this.isOutbound,
    required this.keyHash,
    required this.layer,
  });

  factory SecretChat.fromJson(Map<String, Object?> json) => SecretChat(
    id: tdInt(json['id']),
    userId: tdInt(json['user_id']),
    state: tdObject<SecretChatState>(json['state'], tdFromJson),
    isOutbound: tdBool(json['is_outbound']),
    keyHash: tdBytes(json['key_hash']),
    layer: tdInt(json['layer']),
  );

  static const String constructor = 'secretChat';

  /// Secret chat identifier
  final int id;

  /// Identifier of the chat partner
  final int userId;

  /// State of the secret chat
  final SecretChatState state;

  /// True, if the chat was created by the current user; false otherwise
  final bool isOutbound;

  /// Hash of the currently used key for comparison with the hash of the chat partner's key. This is a string of 36 little-endian bytes, which must be split into groups of 2 bits, each denoting a pixel of one of 4 colors FFFFFF, D5E6F3, 2D5775, and 2F99C9. The pixels must be used to make a 12x12 square image filled from left to right, top to bottom. Alternatively, the first 32 bytes of the hash can be converted to the hexadecimal format and printed as 32 2-digit hex numbers
  final Uint8List keyHash;

  /// Secret chat layer; determines features supported by the chat partner's application. Nested text entities and underline and strikethrough entities are supported if the layer >= 101, files bigger than 2000MB are supported if the layer >= 143, spoiler and custom emoji text entities are supported if the layer >= 144
  final int layer;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'id': id,
    'user_id': userId,
    'state': state.toJson(),
    'is_outbound': isOutbound,
    'key_hash': base64.encode(keyHash),
    'layer': layer,
  };
}

