    required this.id,
    this.staticIcon,
    required this.emoji,
    required this.isPremium,
    required this.type,
  });

  factory MessageEffect.fromJson(Map<String, Object?> json) => MessageEffect(
    id: tdInt64(json['id']),
    staticIcon: tdObjectOrNull<Sticker>(json['static_icon'], tdFromJson),
    emoji: tdString(json['emoji']),
    isPremium: tdBool(json['is_premium']),
    type: tdObject<MessageEffectType>(json['type'], tdFromJson),
  );

  static const String constructor = 'messageEffect';

  /// Unique identifier of the effect
  final int id;

  /// Static icon for the effect in WEBP format; may be null if none
  final Sticker? staticIcon;

  /// Emoji corresponding to the effect that can be used if static icon isn't available
  final String emoji;

  /// True, if Telegram Premium subscription is required to use the effect
  final bool isPremium;

  /// Type of the effect
  final MessageEffectType type;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'id': id.toString(),
    if (staticIcon != null) 'static_icon': staticIcon!.toJson(),
    'emoji': emoji,
    'is_premium': isPremium,
    'type': type.toJson(),
  };
}

/// The message is being sent now, but has not yet been delivered to the server
final class MessageSendingStatePending extends MessageSendingState {
  const MessageSendingStatePending({required this.sendingId});

  factory MessageSendingStatePending.fromJson(Map<String, Object?> json) =>
      MessageSendingStatePending(sendingId: tdInt(json['sending_id']));

  static const String constructor = 'messageSendingStatePending';

  /// Non-persistent message sending identifier, specified by the application
  final int sendingId;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'sending_id': sendingId,
  };
}

/// The message failed to be sent
final class MessageSendingStateFailed extends MessageSendingState {
  const MessageSendingStateFailed({
    required this.error,
    required this.canRetry,
    required this.needAnotherSender,
    required this.needAnotherReplyQuote,
    required this.needDropReply,
    required this.requiredPaidMessageStarCount,
    required this.retryAfter,
  });

  factory MessageSendingStateFailed.fromJson(Map<String, Object?> json) =>
      MessageSendingStateFailed(
        error: tdObject<TdError>(json['error'], tdFromJson),
        canRetry: tdBool(json['can_retry']),
        needAnotherSender: tdBool(json['need_another_sender']),
        needAnotherReplyQuote: tdBool(json['need_another_reply_quote']),
        needDropReply: tdBool(json['need_drop_reply']),
        requiredPaidMessageStarCount: tdInt(
          json['required_paid_message_star_count'],
        ),
        retryAfter: tdDouble(json['retry_after']),
      );

  static const String constructor = 'messageSendingStateFailed';

  /// The cause of the message sending failure
  final TdError error;

  /// True, if the message can be re-sent using resendMessages or readdQuickReplyShortcutMessages
  final bool canRetry;

  /// True, if the message can be re-sent only on behalf of a different sender
  final bool needAnotherSender;

  /// True, if the message can be re-sent only if another quote is chosen in the message that is replied by the given message
  final bool needAnotherReplyQuote;

  /// True, if the message can be re-sent only if the message to be replied is removed. This will be done automatically by resendMessages
  final bool needDropReply;

  /// The number of Telegram Stars that must be paid to send the message; 0 if the current amount is correct
  final int requiredPaidMessageStarCount;

  /// Time left before the message can be re-sent, in seconds. No update is sent when this field changes
  final double retryAfter;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'error': error.toJson(),
    'can_retry': canRetry,
    'need_another_sender': needAnotherSender,
    'need_another_reply_quote': needAnotherReplyQuote,
    'need_drop_reply': needDropReply,
    'required_paid_message_star_count': requiredPaidMessageStarCount,
    'retry_after': retryAfter,
  };
}

/// Describes manually or automatically chosen quote from another message
final class TextQuote extends TdObject {
  const TextQuote({
    required this.text,
    required this.position,
    required this.isManual,
  });

  factory TextQuote.fromJson(Map<String, Object?> json) => TextQuote(
    text: tdObject<FormattedText>(json['text'], tdFromJson),
    position: tdInt(json['position']),
    isManual: tdBool(json['is_manual']),
  );

  static const String constructor = 'textQuote';

  /// Text of the quote. Only Bold, Italic, Underline, Strikethrough, Spoiler, CustomEmoji, and DateTime entities can be present in the text
  final FormattedText text;

  /// Approximate quote position in the original message in UTF-16 code units as specified by the message sender
  final int position;

  /// True, if the quote was manually chosen by the message sender
  final bool isManual;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'text': text.toJson(),
    'position': position,
    'is_manual': isManual,
  };
}

/// Describes manually chosen quote from another message
final class InputTextQuote extends TdObject {
  const InputTextQuote({required this.text, required this.position});

  factory InputTextQuote.fromJson(Map<String, Object?> json) => InputTextQuote(
    text: tdObject<FormattedText>(json['text'], tdFromJson),
    position: tdInt(json['position']),
  );

  static const String constructor = 'inputTextQuote';

  /// Text of the quote; 0-getOption("message_reply_quote_length_max") characters. Only Bold, Italic, Underline, Strikethrough, Spoiler, CustomEmoji, and DateTime entities are allowed to be kept and must be kept in the quote
  final FormattedText text;

  /// Quote position in the original message in UTF-16 code units
  final int position;

  @override
