/// Describes an ephemeral content of a regular message, which must be shown instead of the regular content
final class EphemeralMessageContent extends TdObject {
  const EphemeralMessageContent({
    required this.canBeSaved,
    required this.hasTimestampedMedia,
    required this.content,
    this.replyMarkup,
  });

  factory EphemeralMessageContent.fromJson(Map<String, Object?> json) =>
      EphemeralMessageContent(
        canBeSaved: tdBool(json['can_be_saved']),
        hasTimestampedMedia: tdBool(json['has_timestamped_media']),
        content: tdObject<MessageContent>(json['content'], tdFromJson),
        replyMarkup: tdObjectOrNull<ReplyMarkup>(
          json['reply_markup'],
          tdFromJson,
        ),
      );

  static const String constructor = 'ephemeralMessageContent';

  /// True, if content of the message can be saved locally
  final bool canBeSaved;

  /// True, if media timestamp entities refers to a media in this message as opposed to a media in the replied message
  final bool hasTimestampedMedia;

  /// Content of the message
  final MessageContent content;

  /// Reply markup for the message; may be null if none
  final ReplyMarkup? replyMarkup;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'can_be_saved': canBeSaved,
    'has_timestamped_media': hasTimestampedMedia,
    'content': content.toJson(),
    if (replyMarkup != null) 'reply_markup': replyMarkup!.toJson(),
  };
}

/// Describes a message
final class Message extends TdObject {
  const Message({
    required this.id,
    required this.senderId,
    this.receiverId,
    required this.chatId,
    this.sendingState,
    this.schedulingState,
    required this.isOutgoing,
    required this.isPinned,
    required this.isFromOffline,
    required this.canBeSaved,
    required this.hasTimestampedMedia,
    required this.isChannelPost,
    required this.isPaidStarSuggestedPost,
    required this.isPaidGramSuggestedPost,
    required this.containsUnreadMention,
    required this.containsUnreadPollVotes,
    required this.date,
    required this.editDate,
    this.forwardInfo,
    this.importInfo,
    this.interactionInfo,
    required this.unreadReactions,
    this.factCheck,
    this.suggestedPostInfo,
    this.replyTo,
    this.topicId,
    this.selfDestructType,
    required this.selfDestructIn,
    required this.autoDeleteIn,
    required this.viaBotUserId,
    this.guestBotCallerId,
    required this.senderBusinessBotUserId,
    required this.senderBoostCount,
    required this.senderTag,
    required this.paidMessageStarCount,
    required this.authorSignature,
    required this.mediaAlbumId,
    required this.effectId,
    this.restrictionInfo,
    required this.summaryLanguageCode,
    required this.content,
    this.ephemeralContent,
    this.replyMarkup,
    required this.ephemeralMessageId,
    required this.chatInstance,
  });

  factory Message.fromJson(Map<String, Object?> json) => Message(
    id: tdInt(json['id']),
    senderId: tdObject<MessageSender>(json['sender_id'], tdFromJson),
    receiverId: tdObjectOrNull<MessageSender>(json['receiver_id'], tdFromJson),
    chatId: tdInt(json['chat_id']),
    sendingState: tdObjectOrNull<MessageSendingState>(
      json['sending_state'],
      tdFromJson,
    ),
    schedulingState: tdObjectOrNull<MessageSchedulingState>(
      json['scheduling_state'],
      tdFromJson,
    ),
    isOutgoing: tdBool(json['is_outgoing']),
    isPinned: tdBool(json['is_pinned']),
    isFromOffline: tdBool(json['is_from_offline']),
    canBeSaved: tdBool(json['can_be_saved']),
    hasTimestampedMedia: tdBool(json['has_timestamped_media']),
    isChannelPost: tdBool(json['is_channel_post']),
    isPaidStarSuggestedPost: tdBool(json['is_paid_star_suggested_post']),
    isPaidGramSuggestedPost: tdBool(json['is_paid_gram_suggested_post']),
    containsUnreadMention: tdBool(json['contains_unread_mention']),
    containsUnreadPollVotes: tdBool(json['contains_unread_poll_votes']),
    date: tdInt(json['date']),
    editDate: tdInt(json['edit_date']),
    forwardInfo: tdObjectOrNull<MessageForwardInfo>(
      json['forward_info'],
      tdFromJson,
    ),
    importInfo: tdObjectOrNull<MessageImportInfo>(
      json['import_info'],
      tdFromJson,
    ),
    interactionInfo: tdObjectOrNull<MessageInteractionInfo>(
      json['interaction_info'],
      tdFromJson,
    ),
    unreadReactions: tdList(
      json['unread_reactions'],
      (e) => tdObject<UnreadReaction>(e, tdFromJson),
    ),
    factCheck: tdObjectOrNull<FactCheck>(json['fact_check'], tdFromJson),
    suggestedPostInfo: tdObjectOrNull<SuggestedPostInfo>(
      json['suggested_post_info'],
      tdFromJson,
    ),
    replyTo: tdObjectOrNull<MessageReplyTo>(json['reply_to'], tdFromJson),
    topicId: tdObjectOrNull<MessageTopic>(json['topic_id'], tdFromJson),
    selfDestructType: tdObjectOrNull<MessageSelfDestructType>(
      json['self_destruct_type'],
      tdFromJson,
    ),
    selfDestructIn: tdDouble(json['self_destruct_in']),
    autoDeleteIn: tdDouble(json['auto_delete_in']),
    viaBotUserId: tdInt(json['via_bot_user_id']),
    guestBotCallerId: tdObjectOrNull<MessageSender>(
      json['guest_bot_caller_id'],
      tdFromJson,
    ),
    senderBusinessBotUserId: tdInt(json['sender_business_bot_user_id']),
    senderBoostCount: tdInt(json['sender_boost_count']),
    senderTag: tdString(json['sender_tag']),
    paidMessageStarCount: tdInt(json['paid_message_star_count']),
    authorSignature: tdString(json['author_signature']),
    mediaAlbumId: tdInt64(json['media_album_id']),
    effectId: tdInt64(json['effect_id']),
    restrictionInfo: tdObjectOrNull<RestrictionInfo>(
      json['restriction_info'],
      tdFromJson,
    ),
    summaryLanguageCode: tdString(json['summary_language_code']),
    content: tdObject<MessageContent>(json['content'], tdFromJson),
    ephemeralContent: tdObjectOrNull<EphemeralMessageContent>(
      json['ephemeral_content'],
      tdFromJson,
    ),
    replyMarkup: tdObjectOrNull<ReplyMarkup>(json['reply_markup'], tdFromJson),
    ephemeralMessageId: tdInt(json['ephemeral_message_id']),
    chatInstance: tdInt64(json['chat_instance']),
  );

  static const String constructor = 'message';

  /// Message identifier; unique for the chat to which the message belongs
  final int id;

  /// Identifier of the sender of the message
  final MessageSender senderId;

  /// Identifier of the user or the chat which received the ephemeral message; may be null. Always null for non-ephemeral messages
  final MessageSender? receiverId;

  /// Chat identifier
  final int chatId;

  /// The sending state of the message; may be null if the message isn't being sent and didn't fail to be sent
  final MessageSendingState? sendingState;

  /// The scheduling state of the message; may be null if the message isn't scheduled
  final MessageSchedulingState? schedulingState;

  /// True, if the message is outgoing
  final bool isOutgoing;

  /// True, if the message is pinned
  final bool isPinned;

  /// True, if the message was sent because of a scheduled action by the message sender, for example, as away, or greeting service message
  final bool isFromOffline;

  /// True, if content of the message can be saved locally
  final bool canBeSaved;

  /// True, if media timestamp entities refers to a media in this message as opposed to a media in the replied message
  final bool hasTimestampedMedia;

  /// True, if the message is a channel post. All messages to channels are channel posts, all other messages are not channel posts
  final bool isChannelPost;

  /// True, if the message is a suggested channel post which was paid in Telegram Stars; a warning must be shown if the message is deleted in less than getOption("suggested_post_lifetime_min") seconds after sending
  final bool isPaidStarSuggestedPost;

  /// True, if the message is a suggested channel post which was paid in TON Grams; a warning must be shown if the message is deleted in less than getOption("suggested_post_lifetime_min") seconds after sending
  final bool isPaidGramSuggestedPost;

  /// True, if the message contains an unread mention for the current user
  final bool containsUnreadMention;

  /// True, if the message is a poll message with unread votes
  final bool containsUnreadPollVotes;

  /// Point in time (Unix timestamp) when the message was sent; 0 for scheduled messages
  final int date;

  /// Point in time (Unix timestamp) when the message was last edited; 0 for scheduled messages. If getOption("show_message_edit_date_by_default") is true, then the date must be shown along with the message instead of the date when the message was sent
  final int editDate;

  /// Information about the initial message sender; may be null if none or unknown
  final MessageForwardInfo? forwardInfo;

  /// Information about the initial message for messages created with importMessages; may be null if the message isn't imported
  final MessageImportInfo? importInfo;

  /// Information about interactions with the message; may be null if none
  final MessageInteractionInfo? interactionInfo;

  /// Information about unread reactions added to the message
  final List<UnreadReaction> unreadReactions;

  /// Information about fact-check added to the message; may be null if none
  final FactCheck? factCheck;

  /// Information about the suggested post; may be null if the message isn't a suggested post
  final SuggestedPostInfo? suggestedPostInfo;

  /// Information about the message or the story this message is replying to; may be null if none
  final MessageReplyTo? replyTo;

  /// Identifier of the topic within the chat to which the message belongs; may be null if none; may change when the chat is converted to a forum or back
  final MessageTopic? topicId;

  /// The message's self-destruct type; may be null if none
  final MessageSelfDestructType? selfDestructType;

  /// Time left before the message self-destruct timer expires, in seconds; 0 if self-destruction isn't scheduled yet
  final double selfDestructIn;

  /// Time left before the message will be automatically deleted by message_auto_delete_time setting of the chat, in seconds; 0 if never
  final double autoDeleteIn;

  /// If non-zero, the user identifier of the inline bot through which this message was sent
  final int viaBotUserId;

  /// The identifier of the user or chat which used a guest bot to send the message; may be null if none
  final MessageSender? guestBotCallerId;

  /// If non-zero, the user identifier of the business bot that sent this message
  final int senderBusinessBotUserId;

  /// Number of times the sender of the message boosted the supergroup at the time the message was sent; 0 if none or unknown. For messages sent by the current user, supergroupFullInfo.my_boost_count must be used instead
  final int senderBoostCount;

  /// Tag of the sender of the message in the supergroup at the time the message was sent; may be empty if none or unknown. For messages sent in basic groups or supergroup administrators, the current custom title or tag must be used instead
  final String senderTag;

  /// The number of Telegram Stars the sender paid to send the message
  final int paidMessageStarCount;

  /// For channel posts and anonymous group messages, optional author signature
  final String authorSignature;

  /// Unique identifier of an album this message belongs to; 0 if none. Only audios, documents, photos and videos can be grouped together in albums
  final int mediaAlbumId;

  /// Unique identifier of the effect added to the message; 0 if none
  final int effectId;

  /// Information about the restrictions that must be applied to the message content; may be null if none
  final RestrictionInfo? restrictionInfo;

  /// IETF language tag of the message language on which it can be summarized; empty if summary isn't available for the message
  final String summaryLanguageCode;

  /// Content of the message
  final MessageContent content;

  /// Content of the message, which is visible only to the current user and must be shown instead of the regular content; may be null if none
  final EphemeralMessageContent? ephemeralContent;

  /// Reply markup for the message; may be null if none
  final ReplyMarkup? replyMarkup;

  /// Unique identifier of the ephemeral message if the message is ephemeral; for bots only
  final int ephemeralMessageId;

  /// Identifier that uniquely corresponds to the chat to which the message was sent; for bots only
  final int chatInstance;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'id': id,
    'sender_id': senderId.toJson(),
    if (receiverId != null) 'receiver_id': receiverId!.toJson(),
    'chat_id': chatId,
    if (sendingState != null) 'sending_state': sendingState!.toJson(),
    if (schedulingState != null) 'scheduling_state': schedulingState!.toJson(),
    'is_outgoing': isOutgoing,
    'is_pinned': isPinned,
    'is_from_offline': isFromOffline,
    'can_be_saved': canBeSaved,
    'has_timestamped_media': hasTimestampedMedia,
    'is_channel_post': isChannelPost,
    'is_paid_star_suggested_post': isPaidStarSuggestedPost,
    'is_paid_gram_suggested_post': isPaidGramSuggestedPost,
    'contains_unread_mention': containsUnreadMention,
    'contains_unread_poll_votes': containsUnreadPollVotes,
    'date': date,
    'edit_date': editDate,
    if (forwardInfo != null) 'forward_info': forwardInfo!.toJson(),
    if (importInfo != null) 'import_info': importInfo!.toJson(),
    if (interactionInfo != null) 'interaction_info': interactionInfo!.toJson(),
    'unread_reactions': [for (final e in unreadReactions) e.toJson()],
    if (factCheck != null) 'fact_check': factCheck!.toJson(),
    if (suggestedPostInfo != null)
      'suggested_post_info': suggestedPostInfo!.toJson(),
    if (replyTo != null) 'reply_to': replyTo!.toJson(),
    if (topicId != null) 'topic_id': topicId!.toJson(),
    if (selfDestructType != null)
      'self_destruct_type': selfDestructType!.toJson(),
    'self_destruct_in': selfDestructIn,
    'auto_delete_in': autoDeleteIn,
    'via_bot_user_id': viaBotUserId,
    if (guestBotCallerId != null)
      'guest_bot_caller_id': guestBotCallerId!.toJson(),
    'sender_business_bot_user_id': senderBusinessBotUserId,
    'sender_boost_count': senderBoostCount,
    'sender_tag': senderTag,
    'paid_message_star_count': paidMessageStarCount,
    'author_signature': authorSignature,
    'media_album_id': mediaAlbumId.toString(),
    'effect_id': effectId.toString(),
    if (restrictionInfo != null) 'restriction_info': restrictionInfo!.toJson(),
    'summary_language_code': summaryLanguageCode,
    'content': content.toJson(),
    if (ephemeralContent != null)
      'ephemeral_content': ephemeralContent!.toJson(),
    if (replyMarkup != null) 'reply_markup': replyMarkup!.toJson(),
    'ephemeral_message_id': ephemeralMessageId,
    'chat_instance': chatInstance.toString(),
  };
}

