    required this.additionalInfo,
  });

  factory SponsoredMessage.fromJson(Map<String, Object?> json) =>
      SponsoredMessage(
        messageId: tdInt(json['message_id']),
        isRecommended: tdBool(json['is_recommended']),
        canBeReported: tdBool(json['can_be_reported']),
        content: tdObject<MessageContent>(json['content'], tdFromJson),
        sponsor: tdObject<AdvertisementSponsor>(json['sponsor'], tdFromJson),
        title: tdString(json['title']),
        buttonText: tdString(json['button_text']),
        accentColorId: tdInt(json['accent_color_id']),
        backgroundCustomEmojiId: tdInt64(json['background_custom_emoji_id']),
        additionalInfo: tdString(json['additional_info']),
      );

  static const String constructor = 'sponsoredMessage';

