    required this.maxQuantity,
    required this.requestName,
    required this.requestUsername,
    required this.requestPhoto,
  });

  factory KeyboardButtonTypeRequestUsers.fromJson(Map<String, Object?> json) =>
      KeyboardButtonTypeRequestUsers(
        id: tdInt(json['id']),
        restrictUserIsBot: tdBool(json['restrict_user_is_bot']),
        userIsBot: tdBool(json['user_is_bot']),
        restrictUserIsPremium: tdBool(json['restrict_user_is_premium']),
        userIsPremium: tdBool(json['user_is_premium']),
        maxQuantity: tdInt(json['max_quantity']),
        requestName: tdBool(json['request_name']),
        requestUsername: tdBool(json['request_username']),
        requestPhoto: tdBool(json['request_photo']),
      );

  static const String constructor = 'keyboardButtonTypeRequestUsers';

  /// Unique button identifier
  final int id;

  /// True, if the shared users must or must not be bots
  final bool restrictUserIsBot;

  /// True, if the shared users must be bots; otherwise, the shared users must not be bots. Ignored if restrict_user_is_bot is false
  final bool userIsBot;

  /// True, if the shared users must or must not be Telegram Premium users
  final bool restrictUserIsPremium;

  /// True, if the shared users must be Telegram Premium users; otherwise, the shared users must not be Telegram Premium users. Ignored if restrict_user_is_premium is false
  final bool userIsPremium;

  /// The maximum number of users to share
  final int maxQuantity;

  /// Pass true to request name of the users; bots only
  final bool requestName;

  /// Pass true to request username of the users; bots only
  final bool requestUsername;

  /// Pass true to request photo of the users; bots only
  final bool requestPhoto;

