/// Contains a custom keyboard layout to quickly reply to bots
final class ReplyMarkupShowKeyboard extends ReplyMarkup {
  const ReplyMarkupShowKeyboard({
    required this.rows,
    required this.isPersistent,
    required this.resizeKeyboard,
    required this.oneTime,
    required this.isPersonal,
    required this.forceReply,
    required this.inputFieldPlaceholder,
  });

  factory ReplyMarkupShowKeyboard.fromJson(Map<String, Object?> json) =>
      ReplyMarkupShowKeyboard(
        rows: tdList(
          json['rows'],
          (e) => tdList(e, (e) => tdObject<KeyboardButton>(e, tdFromJson)),
        ),
        isPersistent: tdBool(json['is_persistent']),
        resizeKeyboard: tdBool(json['resize_keyboard']),
        oneTime: tdBool(json['one_time']),
        isPersonal: tdBool(json['is_personal']),
        forceReply: tdBool(json['force_reply']),
        inputFieldPlaceholder: tdString(json['input_field_placeholder']),
      );

  static const String constructor = 'replyMarkupShowKeyboard';

  /// A list of rows of bot keyboard buttons
  final List<List<KeyboardButton>> rows;

  /// True, if the keyboard is expected to always be shown when the ordinary keyboard is hidden
  final bool isPersistent;

  /// True, if the application needs to resize the keyboard vertically
  final bool resizeKeyboard;

  /// True, if the application needs to hide the keyboard after use
  final bool oneTime;

  /// True, if the keyboard must automatically be shown to the current user. For outgoing messages, specify true to show the keyboard only for the mentioned users and for the target user of a reply
  final bool isPersonal;

  /// True, if the keyboard must force reply to the message with the keyboard
  final bool forceReply;

  /// If non-empty, the placeholder to be shown in the input field when the keyboard is active; 0-64 characters
  final String inputFieldPlaceholder;

  @override
  String get tdType => constructor;

  @override
