/// Describes theme settings
final class ThemeSettings extends TdObject {
  const ThemeSettings({
    required this.baseTheme,
    required this.accentColor,
    this.background,
    this.outgoingMessageFill,
    required this.animateOutgoingMessageFill,
    required this.hasOutgoingMessageAccentColor,
    required this.outgoingMessageAccentColor,
  });

  factory ThemeSettings.fromJson(Map<String, Object?> json) => ThemeSettings(
    baseTheme: tdObject<BuiltInTheme>(json['base_theme'], tdFromJson),
    accentColor: tdInt(json['accent_color']),
    background: tdObjectOrNull<Background>(json['background'], tdFromJson),
    outgoingMessageFill: tdObjectOrNull<BackgroundFill>(
      json['outgoing_message_fill'],
      tdFromJson,
    ),
    animateOutgoingMessageFill: tdBool(json['animate_outgoing_message_fill']),
    hasOutgoingMessageAccentColor: tdBool(
      json['has_outgoing_message_accent_color'],
    ),
    outgoingMessageAccentColor: tdInt(json['outgoing_message_accent_color']),
  );

  static const String constructor = 'themeSettings';

  /// Base theme for this theme
  final BuiltInTheme baseTheme;

  /// Theme accent color in ARGB format
  final int accentColor;

  /// The background to be used in chats; may be null
  final Background? background;

  /// The fill to be used as a background for outgoing messages; may be null if the fill from the base theme must be used instead
  final BackgroundFill? outgoingMessageFill;

  /// If true, the freeform gradient fill needs to be animated on every sent message
  final bool animateOutgoingMessageFill;

  /// True, if there is chosen accent color for outgoing messages; otherwise, the color must be deduced from other theme settings
  final bool hasOutgoingMessageAccentColor;

  /// Accent color of outgoing messages in ARGB format; must be ignored if has_outgoing_message_accent_color is false
  final int outgoingMessageAccentColor;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'base_theme': baseTheme.toJson(),
    'accent_color': accentColor,
    if (background != null) 'background': background!.toJson(),
    if (outgoingMessageFill != null)
      'outgoing_message_fill': outgoingMessageFill!.toJson(),
    'animate_outgoing_message_fill': animateOutgoingMessageFill,
    'has_outgoing_message_accent_color': hasOutgoingMessageAccentColor,
    'outgoing_message_accent_color': outgoingMessageAccentColor,
  };
}

/// Represents a button inside a rich message
final class InlineButton extends TdObject {
  const InlineButton({
    required this.text,
    required this.style,
    required this.type,
  });

  factory InlineButton.fromJson(Map<String, Object?> json) => InlineButton(
    text: tdObject<RichText>(json['text'], tdFromJson),
    style: tdObject<ButtonStyle>(json['style'], tdFromJson),
    type: tdObject<InlineKeyboardButtonType>(json['type'], tdFromJson),
  );

  static const String constructor = 'inlineButton';

  /// Text of the button; only richTexts, richTextPlain, and richTextCustomEmoji are allowed
  final RichText text;

  /// Style of the button
  final ButtonStyle style;

  /// Type of the button; must be one of inlineKeyboardButtonTypeUrl, inlineKeyboardButtonTypeLoginUrl, inlineKeyboardButtonTypeWebApp, inlineKeyboardButtonTypeCallback, inlineKeyboardButtonTypeSwitchInline, inlineKeyboardButtonTypeUser, inlineKeyboardButtonTypeCopyText. Additionally, inlineKeyboardButtonTypeCallbackWithPassword and inlineKeyboardButtonTypeDisabled may be received in incoming messages. Regular users may use only inlineKeyboardButtonTypeUrl, inlineKeyboardButtonTypeUser and inlineKeyboardButtonTypeCopyText
  final InlineKeyboardButtonType type;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'text': text.toJson(),
    'style': style.toJson(),
    'type': type.toJson(),
  };
}

