/// A concatenation of rich texts
final class RichTexts extends RichText {
  const RichTexts({required this.texts});

  factory RichTexts.fromJson(Map<String, Object?> json) => RichTexts(
    texts: tdList(json['texts'], (e) => tdObject<RichText>(e, tdFromJson)),
  );

  static const String constructor = 'richTexts';

  /// Texts
  final List<RichText> texts;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'texts': [for (final e in texts) e.toJson()],
  };
}

/// Contains a caption of another block
