  };
}

/// Describes an item of a list page block
final class PageBlockListItem extends TdObject {
  const PageBlockListItem({
    required this.label,
    required this.blocks,
    required this.hasCheckbox,
    required this.isChecked,
    required this.value,
    required this.type,
  });

  factory PageBlockListItem.fromJson(Map<String, Object?> json) =>
      PageBlockListItem(
        label: tdString(json['label']),
        blocks: tdList(
          json['blocks'],
          (e) => tdObject<PageBlock>(e, tdFromJson),
        ),
        hasCheckbox: tdBool(json['has_checkbox']),
        isChecked: tdBool(json['is_checked']),
        value: tdInt(json['value']),
        type: tdString(json['type']),
      );

  static const String constructor = 'pageBlockListItem';

  /// Item label
  final String label;

  /// Item blocks
  final List<PageBlock> blocks;

  /// True, if the item has a checkbox
  final bool hasCheckbox;

  /// True, if the item is checked
  final bool isChecked;

  /// Value of the item; 0 for unordered lists
  final int value;

  /// Type of the item numbering type; must be one of "a" for lowercase letters, "A" for uppercase letters, "i" for lowercase Roman numerals, "I" for uppercase Roman numerals, "1" for decimal numbers, or empty for unordered lists
  final String type;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'label': label,
    'blocks': [for (final e in blocks) e.toJson()],
    'has_checkbox': hasCheckbox,
    'is_checked': isChecked,
    'value': value,
    'type': type,
  };
}

