/// Represents a cell of a table
final class PageBlockTableCell extends TdObject {
  const PageBlockTableCell({
    this.text,
    required this.isHeader,
    required this.colspan,
    required this.rowspan,
    required this.align,
    required this.valign,
  });

  factory PageBlockTableCell.fromJson(
    Map<String, Object?> json,
  ) => PageBlockTableCell(
    text: tdObjectOrNull<RichText>(json['text'], tdFromJson),
    isHeader: tdBool(json['is_header']),
    colspan: tdInt(json['colspan']),
    rowspan: tdInt(json['rowspan']),
    align: tdObject<PageBlockHorizontalAlignment>(json['align'], tdFromJson),
    valign: tdObject<PageBlockVerticalAlignment>(json['valign'], tdFromJson),
  );

  static const String constructor = 'pageBlockTableCell';

  /// Cell text; may be null. If the text is null, then the cell must be invisible
  final RichText? text;

  /// True, if it is a header cell
  final bool isHeader;

  /// The number of columns the cell spans
  final int colspan;

  /// The number of rows the cell spans
  final int rowspan;

  /// Horizontal cell content alignment
  final PageBlockHorizontalAlignment align;

  /// Vertical cell content alignment
  final PageBlockVerticalAlignment valign;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    if (text != null) 'text': text!.toJson(),
    'is_header': isHeader,
    'colspan': colspan,
    'rowspan': rowspan,
    'align': align.toJson(),
    'valign': valign.toJson(),
  };
}

