/// Describes a link preview
final class LinkPreview extends TdObject {
  const LinkPreview({
    required this.url,
    required this.displayUrl,
    required this.siteName,
    required this.title,
    required this.description,
    required this.author,
    required this.type,
    required this.hasLargeMedia,
    required this.showLargeMedia,
    required this.showMediaAboveDescription,
    required this.skipConfirmation,
    required this.showAboveText,
    required this.instantViewVersion,
  });

  factory LinkPreview.fromJson(Map<String, Object?> json) => LinkPreview(
    url: tdString(json['url']),
    displayUrl: tdString(json['display_url']),
    siteName: tdString(json['site_name']),
    title: tdString(json['title']),
    description: tdObject<FormattedText>(json['description'], tdFromJson),
    author: tdString(json['author']),
    type: tdObject<LinkPreviewType>(json['type'], tdFromJson),
    hasLargeMedia: tdBool(json['has_large_media']),
    showLargeMedia: tdBool(json['show_large_media']),
    showMediaAboveDescription: tdBool(json['show_media_above_description']),
    skipConfirmation: tdBool(json['skip_confirmation']),
    showAboveText: tdBool(json['show_above_text']),
    instantViewVersion: tdInt(json['instant_view_version']),
  );

  static const String constructor = 'linkPreview';

  /// Original URL of the link
  final String url;

  /// URL to display
  final String displayUrl;

  /// Short name of the website (e.g., Google Docs, App Store)
  final String siteName;

  /// Title of the content
  final String title;

  /// Description of the content
  final FormattedText description;

  /// Author of the content
  final String author;

  /// Type of the link preview
  final LinkPreviewType type;

  /// True, if size of media in the preview can be changed
  final bool hasLargeMedia;

  /// True, if large media preview must be shown; otherwise, the media preview must be shown small and only the first frame must be shown for videos
  final bool showLargeMedia;

  /// True, if media must be shown above link preview description; otherwise, the media must be shown below the description
  final bool showMediaAboveDescription;

  /// True, if there is no need to show an ordinary open URL confirmation, when opening the URL from the preview, because the URL is shown in the message text in clear
  final bool skipConfirmation;

  /// True, if the link preview must be shown above message text; otherwise, the link preview must be shown below the message text
  final bool showAboveText;

  /// Version of instant view (currently, can be 1 or 2) for the web page; 0 if none
  final int instantViewVersion;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'url': url,
    'display_url': displayUrl,
    'site_name': siteName,
    'title': title,
    'description': description.toJson(),
    'author': author,
    'type': type.toJson(),
    'has_large_media': hasLargeMedia,
    'show_large_media': showLargeMedia,
    'show_media_above_description': showMediaAboveDescription,
    'skip_confirmation': skipConfirmation,
    'show_above_text': showAboveText,
    'instant_view_version': instantViewVersion,
  };
}

