/// Product invoice
final class Invoice extends TdObject {
  const Invoice({
    required this.currency,
    required this.priceParts,
    required this.subscriptionPeriod,
    required this.maxTipAmount,
    required this.suggestedTipAmounts,
    required this.recurringPaymentTermsOfServiceUrl,
    required this.termsOfServiceUrl,
    required this.isTest,
    required this.needName,
    required this.needPhoneNumber,
    required this.needEmailAddress,
    required this.needShippingAddress,
    required this.sendPhoneNumberToProvider,
    required this.sendEmailAddressToProvider,
    required this.isFlexible,
  });

  factory Invoice.fromJson(Map<String, Object?> json) => Invoice(
    currency: tdString(json['currency']),
    priceParts: tdList(
      json['price_parts'],
      (e) => tdObject<LabeledPricePart>(e, tdFromJson),
    ),
    subscriptionPeriod: tdInt(json['subscription_period']),
    maxTipAmount: tdInt(json['max_tip_amount']),
    suggestedTipAmounts: tdList(json['suggested_tip_amounts'], (e) => tdInt(e)),
    recurringPaymentTermsOfServiceUrl: tdString(
      json['recurring_payment_terms_of_service_url'],
    ),
    termsOfServiceUrl: tdString(json['terms_of_service_url']),
    isTest: tdBool(json['is_test']),
    needName: tdBool(json['need_name']),
    needPhoneNumber: tdBool(json['need_phone_number']),
    needEmailAddress: tdBool(json['need_email_address']),
    needShippingAddress: tdBool(json['need_shipping_address']),
    sendPhoneNumberToProvider: tdBool(json['send_phone_number_to_provider']),
    sendEmailAddressToProvider: tdBool(json['send_email_address_to_provider']),
    isFlexible: tdBool(json['is_flexible']),
  );

  static const String constructor = 'invoice';

  /// ISO 4217 currency code
  final String currency;

  /// A list of objects used to calculate the total price of the product
  final List<LabeledPricePart> priceParts;

  /// The number of seconds between consecutive Telegram Star debiting for subscription invoices; 0 if the invoice doesn't create subscription
  final int subscriptionPeriod;

  /// The maximum allowed amount of tip in the smallest units of the currency
  final int maxTipAmount;

  /// Suggested amounts of tip in the smallest units of the currency
  final List<int> suggestedTipAmounts;

  /// An HTTP URL with terms of service for recurring payments. If non-empty, the invoice payment will result in recurring payments and the user must accept the terms of service before allowed to pay
  final String recurringPaymentTermsOfServiceUrl;

  /// An HTTP URL with terms of service for non-recurring payments. If non-empty, then the user must accept the terms of service before allowed to pay
  final String termsOfServiceUrl;

  /// True, if the payment is a test payment
  final bool isTest;

  /// True, if the user's name is needed for payment
  final bool needName;

  /// True, if the user's phone number is needed for payment
  final bool needPhoneNumber;

  /// True, if the user's email address is needed for payment
  final bool needEmailAddress;

  /// True, if the user's shipping address is needed for payment
  final bool needShippingAddress;

  /// True, if the user's phone number will be sent to the provider
  final bool sendPhoneNumberToProvider;

  /// True, if the user's email address will be sent to the provider
  final bool sendEmailAddressToProvider;

  /// True, if the total price depends on the shipping method
  final bool isFlexible;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'currency': currency,
    'price_parts': [for (final e in priceParts) e.toJson()],
    'subscription_period': subscriptionPeriod,
    'max_tip_amount': maxTipAmount,
    'suggested_tip_amounts': suggestedTipAmounts,
    'recurring_payment_terms_of_service_url': recurringPaymentTermsOfServiceUrl,
    'terms_of_service_url': termsOfServiceUrl,
    'is_test': isTest,
    'need_name': needName,
    'need_phone_number': needPhoneNumber,
    'need_email_address': needEmailAddress,
    'need_shipping_address': needShippingAddress,
    'send_phone_number_to_provider': sendPhoneNumberToProvider,
    'send_email_address_to_provider': sendEmailAddressToProvider,
    'is_flexible': isFlexible,
  };
}

