/// Contains information about an encrypted Telegram Passport element; for bots only
final class EncryptedPassportElement extends TdObject {
  const EncryptedPassportElement({
    required this.type,
    required this.data,
    required this.frontSide,
    this.reverseSide,
    this.selfie,
    required this.translation,
    required this.files,
    required this.value,
    required this.hash,
  });

  factory EncryptedPassportElement.fromJson(Map<String, Object?> json) =>
      EncryptedPassportElement(
        type: tdObject<PassportElementType>(json['type'], tdFromJson),
        data: tdBytes(json['data']),
        frontSide: tdObject<DatedFile>(json['front_side'], tdFromJson),
        reverseSide: tdObjectOrNull<DatedFile>(
          json['reverse_side'],
          tdFromJson,
        ),
        selfie: tdObjectOrNull<DatedFile>(json['selfie'], tdFromJson),
        translation: tdList(
          json['translation'],
          (e) => tdObject<DatedFile>(e, tdFromJson),
        ),
        files: tdList(json['files'], (e) => tdObject<DatedFile>(e, tdFromJson)),
        value: tdString(json['value']),
        hash: tdString(json['hash']),
      );

  static const String constructor = 'encryptedPassportElement';

  /// Type of Telegram Passport element
  final PassportElementType type;

  /// Encrypted JSON-encoded data about the user
  final Uint8List data;

  /// The front side of an identity document
  final DatedFile frontSide;

  /// The reverse side of an identity document; may be null
  final DatedFile? reverseSide;

  /// Selfie with the document; may be null
  final DatedFile? selfie;

  /// List of files containing a certified English translation of the document
  final List<DatedFile> translation;

  /// List of attached files
  final List<DatedFile> files;

  /// Unencrypted data, phone number or email address
  final String value;

  /// Hash of the entire element
  final String hash;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'type': type.toJson(),
    'data': base64.encode(data),
    'front_side': frontSide.toJson(),
    if (reverseSide != null) 'reverse_side': reverseSide!.toJson(),
    if (selfie != null) 'selfie': selfie!.toJson(),
    'translation': [for (final e in translation) e.toJson()],
    'files': [for (final e in files) e.toJson()],
    'value': value,
    'hash': hash,
  };
}

