  const MessageRichMessage({required this.message});

  factory MessageRichMessage.fromJson(Map<String, Object?> json) =>
      MessageRichMessage(
        message: tdObject<RichMessage>(json['message'], tdFromJson),
      );

  static const String constructor = 'messageRichMessage';

  /// The rich message
  final RichMessage message;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'message': message.toJson(),
  };
}

/// An animation message (GIF-style).
final class MessageAnimation extends MessageContent {
  const MessageAnimation({
    required this.animation,
    required this.caption,
    required this.showCaptionAboveMedia,
    required this.hasSpoiler,
    required this.isSecret,
  });

  factory MessageAnimation.fromJson(Map<String, Object?> json) =>
      MessageAnimation(
        animation: tdObject<Animation>(json['animation'], tdFromJson),
        caption: tdObject<FormattedText>(json['caption'], tdFromJson),
        showCaptionAboveMedia: tdBool(json['show_caption_above_media']),
        hasSpoiler: tdBool(json['has_spoiler']),
        isSecret: tdBool(json['is_secret']),
      );

  static const String constructor = 'messageAnimation';

  /// The animation description
  final Animation animation;

  /// Animation caption
  final FormattedText caption;

  /// True, if the caption must be shown above the animation; otherwise, the caption must be shown below the animation
  final bool showCaptionAboveMedia;

  /// True, if the animation preview must be covered by a spoiler animation
  final bool hasSpoiler;

  /// True, if the animation thumbnail must be blurred and the animation must be shown only while tapped
  final bool isSecret;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'animation': animation.toJson(),
    'caption': caption.toJson(),
    'show_caption_above_media': showCaptionAboveMedia,
    'has_spoiler': hasSpoiler,
    'is_secret': isSecret,
  };
}

