/// A video message
final class MessageVideo extends MessageContent {
  const MessageVideo({
    required this.video,
    required this.alternativeVideos,
    required this.storyboards,
    this.cover,
    required this.startTimestamp,
    required this.caption,
    required this.showCaptionAboveMedia,
    required this.hasSpoiler,
    required this.isSecret,
  });

  factory MessageVideo.fromJson(Map<String, Object?> json) => MessageVideo(
    video: tdObject<Video>(json['video'], tdFromJson),
    alternativeVideos: tdList(
      json['alternative_videos'],
      (e) => tdObject<AlternativeVideo>(e, tdFromJson),
    ),
    storyboards: tdList(
      json['storyboards'],
      (e) => tdObject<VideoStoryboard>(e, tdFromJson),
    ),
    cover: tdObjectOrNull<Photo>(json['cover'], tdFromJson),
    startTimestamp: tdInt(json['start_timestamp']),
    caption: tdObject<FormattedText>(json['caption'], tdFromJson),
    showCaptionAboveMedia: tdBool(json['show_caption_above_media']),
    hasSpoiler: tdBool(json['has_spoiler']),
    isSecret: tdBool(json['is_secret']),
  );

  static const String constructor = 'messageVideo';

  /// The video description
  final Video video;

  /// Alternative qualities of the video
  final List<AlternativeVideo> alternativeVideos;

  /// Available storyboards for the video
  final List<VideoStoryboard> storyboards;

  /// Cover of the video; may be null if none
  final Photo? cover;

  /// Timestamp from which the video playing must start, in seconds
  final int startTimestamp;

  /// Video caption
  final FormattedText caption;

  /// True, if the caption must be shown above the video; otherwise, the caption must be shown below the video
  final bool showCaptionAboveMedia;

  /// True, if the video preview must be covered by a spoiler animation
  final bool hasSpoiler;

  /// True, if the video thumbnail must be blurred and the video must be shown only while tapped
  final bool isSecret;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'video': video.toJson(),
    'alternative_videos': [for (final e in alternativeVideos) e.toJson()],
    'storyboards': [for (final e in storyboards) e.toJson()],
    if (cover != null) 'cover': cover!.toJson(),
    'start_timestamp': startTimestamp,
    'caption': caption.toJson(),
    'show_caption_above_media': showCaptionAboveMedia,
    'has_spoiler': hasSpoiler,
    'is_secret': isSecret,
  };
}

