/// A dice message. The dice value is randomly generated by the server
final class MessageDice extends MessageContent {
  const MessageDice({
    this.initialState,
    this.finalState,
    required this.emoji,
    required this.value,
    required this.successAnimationFrameNumber,
  });

  factory MessageDice.fromJson(Map<String, Object?> json) => MessageDice(
    initialState: tdObjectOrNull<DiceStickers>(
      json['initial_state'],
      tdFromJson,
    ),
    finalState: tdObjectOrNull<DiceStickers>(json['final_state'], tdFromJson),
    emoji: tdString(json['emoji']),
    value: tdInt(json['value']),
    successAnimationFrameNumber: tdInt(json['success_animation_frame_number']),
  );

  static const String constructor = 'messageDice';

  /// The animated stickers with the initial dice animation; may be null if unknown. The update updateMessageContent will be sent when the sticker became known
  final DiceStickers? initialState;

  /// The animated stickers with the final dice animation; may be null if unknown. The update updateMessageContent will be sent when the sticker became known
  final DiceStickers? finalState;

  /// Emoji on which the dice throw animation is based
  final String emoji;

  /// The dice value. If the value is 0, then the dice don't have final state yet
  final int value;

  /// Number of frame after which a success animation like a shower of confetti needs to be shown on updateMessageSendSucceeded
  final int successAnimationFrameNumber;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    if (initialState != null) 'initial_state': initialState!.toJson(),
    if (finalState != null) 'final_state': finalState!.toJson(),
    'emoji': emoji,
    'value': value,
    'success_animation_frame_number': successAnimationFrameNumber,
  };
}

