/// A message with an invoice from a bot. Use getInternalLink with internalLinkTypeBotStart to share the invoice
final class MessageInvoice extends MessageContent {
  const MessageInvoice({
    required this.productInfo,
    required this.currency,
    required this.totalAmount,
    required this.startParameter,
    required this.isTest,
    required this.needShippingAddress,
    required this.receiptMessageId,
    this.paidMedia,
    this.paidMediaCaption,
  });

  factory MessageInvoice.fromJson(Map<String, Object?> json) => MessageInvoice(
    productInfo: tdObject<ProductInfo>(json['product_info'], tdFromJson),
    currency: tdString(json['currency']),
    totalAmount: tdInt(json['total_amount']),
    startParameter: tdString(json['start_parameter']),
    isTest: tdBool(json['is_test']),
    needShippingAddress: tdBool(json['need_shipping_address']),
    receiptMessageId: tdInt(json['receipt_message_id']),
    paidMedia: tdObjectOrNull<PaidMedia>(json['paid_media'], tdFromJson),
    paidMediaCaption: tdObjectOrNull<FormattedText>(
      json['paid_media_caption'],
      tdFromJson,
    ),
  );

  static const String constructor = 'messageInvoice';

  /// Information about the product
  final ProductInfo productInfo;

  /// Currency for the product price
  final String currency;

  /// Product total price in the smallest units of the currency
  final int totalAmount;

  /// Unique invoice bot start_parameter to be passed to getInternalLink
  final String startParameter;

  /// True, if the invoice is a test invoice
  final bool isTest;

  /// True, if the shipping address must be specified
  final bool needShippingAddress;

  /// The identifier of the message with the receipt, after the product has been purchased
  final int receiptMessageId;

  /// Extended media attached to the invoice; may be null if none
  final PaidMedia? paidMedia;

  /// Extended media caption; may be null if none
  final FormattedText? paidMediaCaption;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'product_info': productInfo.toJson(),
    'currency': currency,
    'total_amount': totalAmount,
    'start_parameter': startParameter,
    'is_test': isTest,
    'need_shipping_address': needShippingAddress,
    'receipt_message_id': receiptMessageId,
    if (paidMedia != null) 'paid_media': paidMedia!.toJson(),
    if (paidMediaCaption != null)
      'paid_media_caption': paidMediaCaption!.toJson(),
  };
}

/// A message with information about an ended call
final class MessageCall extends MessageContent {
  const MessageCall({
    required this.uniqueId,
