        photoSize: tdInt(json['photo_size']),
        photoWidth: tdInt(json['photo_width']),
        photoHeight: tdInt(json['photo_height']),
        payload: tdBytes(json['payload']),
        providerToken: tdString(json['provider_token']),
        providerData: tdString(json['provider_data']),
        startParameter: tdString(json['start_parameter']),
        paidMedia: tdObjectOrNull<InputPaidMedia>(
          json['paid_media'],
          tdFromJson,
        ),
