/// Represents the results of the inline query. Use sendInlineQueryResultMessage to send the result of the query
final class InlineQueryResults extends TdObject {
  const InlineQueryResults({
    required this.inlineQueryId,
    this.button,
    required this.results,
    required this.nextOffset,
  });

  factory InlineQueryResults.fromJson(Map<String, Object?> json) =>
      InlineQueryResults(
        inlineQueryId: tdInt64(json['inline_query_id']),
        button: tdObjectOrNull<InlineQueryResultsButton>(
          json['button'],
          tdFromJson,
        ),
        results: tdList(
          json['results'],
          (e) => tdObject<InlineQueryResult>(e, tdFromJson),
        ),
        nextOffset: tdString(json['next_offset']),
      );

  static const String constructor = 'inlineQueryResults';

  /// Unique identifier of the inline query
  final int inlineQueryId;

  /// Button to be shown above inline query results; may be null
  final InlineQueryResultsButton? button;

  /// Results of the query
  final List<InlineQueryResult> results;

  /// The offset for the next request. If empty, then there are no more results
  final String nextOffset;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'inline_query_id': inlineQueryId.toString(),
    if (button != null) 'button': button!.toJson(),
    'results': [for (final e in results) e.toJson()],
    'next_offset': nextOffset,
  };
}

