/// Contains information about a language pack
final class LanguagePackInfo extends TdObject {
  const LanguagePackInfo({
    required this.id,
    required this.baseLanguagePackId,
    required this.name,
    required this.nativeName,
    required this.pluralCode,
    required this.isOfficial,
    required this.isRtl,
    required this.isBeta,
    required this.isInstalled,
    required this.totalStringCount,
    required this.translatedStringCount,
    required this.localStringCount,
    required this.translationUrl,
  });

  factory LanguagePackInfo.fromJson(Map<String, Object?> json) =>
      LanguagePackInfo(
        id: tdString(json['id']),
        baseLanguagePackId: tdString(json['base_language_pack_id']),
        name: tdString(json['name']),
        nativeName: tdString(json['native_name']),
        pluralCode: tdString(json['plural_code']),
        isOfficial: tdBool(json['is_official']),
        isRtl: tdBool(json['is_rtl']),
        isBeta: tdBool(json['is_beta']),
        isInstalled: tdBool(json['is_installed']),
        totalStringCount: tdInt(json['total_string_count']),
        translatedStringCount: tdInt(json['translated_string_count']),
        localStringCount: tdInt(json['local_string_count']),
        translationUrl: tdString(json['translation_url']),
      );

  static const String constructor = 'languagePackInfo';

  /// Unique language pack identifier
  final String id;

  /// Identifier of a base language pack; may be empty. If a string is missed in the language pack, then it must be fetched from base language pack. Unsupported in custom language packs
  final String baseLanguagePackId;

  /// Language name
  final String name;

  /// Name of the language in that language
  final String nativeName;

  /// A language code to be used to apply plural forms. See https://www.unicode.org/cldr/charts/latest/supplemental/language_plural_rules.html for more information
  final String pluralCode;

  /// True, if the language pack is official
  final bool isOfficial;

  /// True, if the language pack strings are RTL
  final bool isRtl;

  /// True, if the language pack is a beta language pack
  final bool isBeta;

  /// True, if the language pack is installed by the current user
  final bool isInstalled;

  /// Total number of non-deleted strings from the language pack
  final int totalStringCount;

  /// Total number of translated strings from the language pack
  final int translatedStringCount;

  /// Total number of non-deleted strings from the language pack available locally
  final int localStringCount;

  /// Link to language translation interface; empty for custom local language packs
  final String translationUrl;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'id': id,
    'base_language_pack_id': baseLanguagePackId,
    'name': name,
    'native_name': nativeName,
    'plural_code': pluralCode,
    'is_official': isOfficial,
    'is_rtl': isRtl,
    'is_beta': isBeta,
    'is_installed': isInstalled,
    'total_string_count': totalStringCount,
    'translated_string_count': translatedStringCount,
    'local_string_count': localStringCount,
    'translation_url': translationUrl,
  };
}

