/// Contains information about one session in a Telegram application used by the current user. Sessions must be shown to the user in the returned order
final class Session extends TdObject {
  const Session({
    required this.id,
    required this.isCurrent,
    required this.isPasswordPending,
    required this.isUnconfirmed,
    required this.canAcceptSecretChats,
    required this.canAcceptCalls,
    required this.deviceType,
    required this.apiId,
    required this.applicationName,
    required this.applicationVersion,
    required this.isOfficialApplication,
    required this.deviceModel,
    required this.platform,
    required this.systemVersion,
    required this.logInDate,
    required this.lastActiveDate,
    required this.ipAddress,
    required this.location,
  });

  factory Session.fromJson(Map<String, Object?> json) => Session(
    id: tdInt64(json['id']),
    isCurrent: tdBool(json['is_current']),
    isPasswordPending: tdBool(json['is_password_pending']),
    isUnconfirmed: tdBool(json['is_unconfirmed']),
    canAcceptSecretChats: tdBool(json['can_accept_secret_chats']),
    canAcceptCalls: tdBool(json['can_accept_calls']),
    deviceType: tdObject<SessionDeviceType>(json['device_type'], tdFromJson),
    apiId: tdInt(json['api_id']),
    applicationName: tdString(json['application_name']),
    applicationVersion: tdString(json['application_version']),
    isOfficialApplication: tdBool(json['is_official_application']),
    deviceModel: tdString(json['device_model']),
    platform: tdString(json['platform']),
    systemVersion: tdString(json['system_version']),
    logInDate: tdInt(json['log_in_date']),
    lastActiveDate: tdInt(json['last_active_date']),
    ipAddress: tdString(json['ip_address']),
    location: tdString(json['location']),
  );

  static const String constructor = 'session';

  /// Session identifier
  final int id;

  /// True, if this session is the current session
  final bool isCurrent;

  /// True, if a 2-step verification password is needed to complete authorization of the session
  final bool isPasswordPending;

  /// True, if the session wasn't confirmed from another session
  final bool isUnconfirmed;

  /// True, if incoming secret chats can be accepted by the session
  final bool canAcceptSecretChats;

  /// True, if incoming calls can be accepted by the session
  final bool canAcceptCalls;

  /// Session device type based on the system and application version, which can be used to display a corresponding icon
  final SessionDeviceType deviceType;

  /// Telegram API identifier, as provided by the application
  final int apiId;

  /// Name of the application, as provided by the application
  final String applicationName;

  /// The version of the application, as provided by the application
  final String applicationVersion;

  /// True, if the application is an official application or uses the api_id of an official application
  final bool isOfficialApplication;

  /// Model of the device the application has been run or is running on, as provided by the application
  final String deviceModel;

  /// Operating system the application has been run or is running on, as provided by the application
  final String platform;

  /// Version of the operating system the application has been run or is running on, as provided by the application
  final String systemVersion;

  /// Point in time (Unix timestamp) when the user has logged in
  final int logInDate;

  /// Point in time (Unix timestamp) when the session was last used
  final int lastActiveDate;

  /// IP address from which the session was created, in human-readable format
  final String ipAddress;

  /// A human-readable description of the location from which the session was created, based on the IP address
  final String location;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'id': id.toString(),
    'is_current': isCurrent,
    'is_password_pending': isPasswordPending,
    'is_unconfirmed': isUnconfirmed,
    'can_accept_secret_chats': canAcceptSecretChats,
    'can_accept_calls': canAcceptCalls,
    'device_type': deviceType.toJson(),
    'api_id': apiId,
    'application_name': applicationName,
    'application_version': applicationVersion,
    'is_official_application': isOfficialApplication,
    'device_model': deviceModel,
    'platform': platform,
    'system_version': systemVersion,
    'log_in_date': logInDate,
    'last_active_date': lastActiveDate,
    'ip_address': ipAddress,
    'location': location,
  };
}

/// Contains a list of sessions
final class Sessions extends TdObject {
  const Sessions({
    required this.sessions,
    required this.inactiveSessionTtlDays,
  });

  factory Sessions.fromJson(Map<String, Object?> json) => Sessions(
    sessions: tdList(json['sessions'], (e) => tdObject<Session>(e, tdFromJson)),
    inactiveSessionTtlDays: tdInt(json['inactive_session_ttl_days']),
  );

  static const String constructor = 'sessions';

  /// List of sessions
  final List<Session> sessions;

  /// Number of days of inactivity before sessions will automatically be terminated; 1-366 days
  final int inactiveSessionTtlDays;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'sessions': [for (final e in sessions) e.toJson()],
    'inactive_session_ttl_days': inactiveSessionTtlDays,
  };
}

/// Contains information about an unconfirmed session
final class UnconfirmedSession extends TdObject {
  const UnconfirmedSession({
    required this.type,
    required this.date,
    required this.deviceModel,
    required this.location,
  });

  factory UnconfirmedSession.fromJson(Map<String, Object?> json) =>
      UnconfirmedSession(
        type: tdObject<SessionType>(json['type'], tdFromJson),
        date: tdInt(json['date']),
        deviceModel: tdString(json['device_model']),
        location: tdString(json['location']),
      );

  static const String constructor = 'unconfirmedSession';

  /// Session type
  final SessionType type;

  /// Point in time (Unix timestamp) when the user has logged in or the business bot was connected
  final int date;

  /// Model of the device that was used for the session creation, as provided by the application
  final String deviceModel;

  /// A human-readable description of the location from which the session was created, based on the IP address
  final String location;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'type': type.toJson(),
    'date': date,
    'device_model': deviceModel,
    'location': location,
  };
}

