/// Contains information about the total amount of data that was used to send and receive files
final class NetworkStatisticsEntryFile extends NetworkStatisticsEntry {
  const NetworkStatisticsEntryFile({
    this.fileType,
    required this.networkType,
    required this.sentBytes,
    required this.receivedBytes,
  });

  factory NetworkStatisticsEntryFile.fromJson(Map<String, Object?> json) =>
      NetworkStatisticsEntryFile(
        fileType: tdObjectOrNull<FileType>(json['file_type'], tdFromJson),
        networkType: tdObject<NetworkType>(json['network_type'], tdFromJson),
        sentBytes: tdInt(json['sent_bytes']),
        receivedBytes: tdInt(json['received_bytes']),
      );

  static const String constructor = 'networkStatisticsEntryFile';

  /// Type of the file the data is part of; pass null if the data isn't related to files
  final FileType? fileType;

  /// Type of the network the data was sent through. Call setNetworkType to maintain the actual network type
  final NetworkType networkType;

  /// Total number of bytes sent
  final int sentBytes;

  /// Total number of bytes received
  final int receivedBytes;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    if (fileType != null) 'file_type': fileType!.toJson(),
    'network_type': networkType.toJson(),
    'sent_bytes': sentBytes,
    'received_bytes': receivedBytes,
