/// Sends a message. Returns the sent message
///
/// Returns [Message].
final class SendMessage extends TdFunction<Message> {
  const SendMessage({
    required this.chatId,
    this.topicId,
    this.replyTo,
    this.options,
    this.replyMarkup,
    required this.inputMessageContent,
  });

  static const String constructor = 'sendMessage';

  /// Target chat
  final int chatId;

  /// Topic in which the message will be sent; pass null if none
  final MessageTopic? topicId;

  /// Information about the message or story to be replied; pass null if none
  final InputMessageReplyTo? replyTo;

  /// Options to be used to send the message; pass null to use default options
  final MessageSendOptions? options;

  /// Markup for replying to the message; pass null if none; for bots only
  final ReplyMarkup? replyMarkup;

  /// The content of the message to be sent
  final InputMessageContent inputMessageContent;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'chat_id': chatId,
    if (topicId != null) 'topic_id': topicId!.toJson(),
    if (replyTo != null) 'reply_to': replyTo!.toJson(),
    if (options != null) 'options': options!.toJson(),
    if (replyMarkup != null) 'reply_markup': replyMarkup!.toJson(),
    'input_message_content': inputMessageContent.toJson(),
  };
}

/// Sends 2-10 messages grouped together into an album. Currently, only audio, document, photo and video messages can be grouped into an album. Documents and audio files can be only grouped in an album with messages of the same type. Returns sent messages
///
/// Returns [Messages].
final class SendMessageAlbum extends TdFunction<Messages> {
  const SendMessageAlbum({
    required this.chatId,
    this.topicId,
    this.replyTo,
    this.options,
    required this.inputMessageContents,
  });

  static const String constructor = 'sendMessageAlbum';

  /// Target chat
  final int chatId;

  /// Topic in which the messages will be sent; pass null if none
  final MessageTopic? topicId;

  /// Information about the message or story to be replied; pass null if none
  final InputMessageReplyTo? replyTo;

  /// Options to be used to send the messages; pass null to use default options
  final MessageSendOptions? options;

  /// Contents of messages to be sent. At most 10 messages can be added to an album. All messages must have the same value of show_caption_above_media
  final List<InputMessageContent> inputMessageContents;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'chat_id': chatId,
    if (topicId != null) 'topic_id': topicId!.toJson(),
    if (replyTo != null) 'reply_to': replyTo!.toJson(),
    if (options != null) 'options': options!.toJson(),
    'input_message_contents': [
      for (final e in inputMessageContents) e.toJson(),
    ],
  };
}

