///
/// Returns [TdError].
final class TestReturnError extends TdFunction<TdError> {
  const TestReturnError({required this.error});

  static const String constructor = 'testReturnError';

  /// The error to be returned
  final TdError error;

  @override
  String get tdType => constructor;

  @override
  Map<String, Object?> toJson() => {
    '@type': constructor,
    'error': error.toJson(),
  };
}

/// Разбирает объект td_api по полю `@type`.
TdObject tdFromJson(Map<String, Object?> json) {
  final type = json['@type'];
  final decode = _decoders[type];
  if (decode == null) {
    throw TdDecodeException('Unknown @type: $type');
  }
  return decode(json);
}

